const html = $input.item.json.data || $input.item.json.body || '';

function cleanText(str) {
  if (!str) return 'N/A';
  return str.replace(/<[^>]*>/g, '').replace(/,/g, '').replace(/\s+/g, ' ').trim() || 'N/A';
}

function getTopCardMetric(label, htmlString) {
  const regex = new RegExp(`<li[^>]*>[\\s\\S]*?<span class="name">\\s*${label}\\s*<\\/span>[\\s\\S]*?<span class="number">(.*?)<\\/span>`, 'i');
  const match = htmlString.match(regex);
  return match ? cleanText(match[1]) : 'N/A';
}

// Fixed CMP & Precise Change % Extraction
function getLivePriceDetails(htmlString) {
  let price = getTopCardMetric('Current Price', htmlString);
  let changePct = '';
  let priceTime = '';

  if (price === 'N/A') {
    const rawPrice = htmlString.match(/₹\s*([0-9,]+(?:\.[0-9]+)?)/);
    if (rawPrice) price = rawPrice[1].replace(/,/g, '').trim();
  }

  // Scrape direct class element for green/red percentage change
  const priceChangeMatch = htmlString.match(/<span[^>]*class="[^\"]*(green|red)[^\"]*"[^>]*>\s*([+-]?\s*[0-9]+(?:\.[0-9]+)?%)\s*<\/span>/i) ||
                           htmlString.match(/(?:green|red)[^>]*>\s*([+-]?\d+(?:\.\d+)?%)/i);

  if (priceChangeMatch) {
    const isRed = priceChangeMatch[0].toLowerCase().includes('red');
    let rawPct = priceChangeMatch[2] || priceChangeMatch[1];
    rawPct = rawPct.replace(/\s+/g, '');
    if (!rawPct.startsWith('+') && !rawPct.startsWith('-')) {
      changePct = isRed ? `-${rawPct}` : `+${rawPct}`;
    } else {
      changePct = rawPct;
    }
  }

  // Scrape timestamp e.g. "29 Jul 2:49 p.m."
  const timeMatch = htmlString.match(/(\d{1,2}\s+[A-Za-z]{3}\s+\d{1,2}:\d{2}\s*(?:a\.m\.|p\.m\.|AM|PM)?)/i);
  if (timeMatch) {
    priceTime = timeMatch[1].replace(/\s+/g, ' ').trim();
  }

  return { price, changePct, priceTime };
}

function getHighLowMetric(htmlString) {
  const regex = new RegExp(`<li[^>]*>[\\s\\S]*?<span class="name">\\s*High\\s*\\/\\s*Low\\s*<\\/span>([\\s\\S]*?)<\\/li>`, 'i');
  const match = htmlString.match(regex);
  if (!match) return 'N/A';

  const numbers = [];
  const numRegex = /<span class="number">(.*?)<\/span>/gi;
  let numMatch;
  while ((numMatch = numRegex.exec(match[1])) !== null) {
    numbers.push(cleanText(numMatch[1]));
  }

  if (numbers.length >= 2) return `${numbers[0]} / ${numbers[1]}`;
  if (numbers.length === 1) return numbers[0];
  return 'N/A';
}

